CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_internationalpayments]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_contactid] = stg.[apuk_contactid],
		tgt.[apuk_contactid_entitytype] = stg.[apuk_contactid_entitytype],
		tgt.[apuk_contactidname] = stg.[apuk_contactidname],
		tgt.[apuk_contactidyominame] = stg.[apuk_contactidyominame],
		tgt.[apuk_country] = stg.[apuk_country],
		tgt.[apuk_dateprocessed] = stg.[apuk_dateprocessed],
		tgt.[apuk_internationalpaymentsid] = stg.[apuk_internationalpaymentsid],
		tgt.[apuk_localgroup] = stg.[apuk_localgroup],
		tgt.[apuk_localgroupid] = stg.[apuk_localgroupid],
		tgt.[apuk_localgroupid_entitytype] = stg.[apuk_localgroupid_entitytype],
		tgt.[apuk_localgroupidname] = stg.[apuk_localgroupidname],
		tgt.[apuk_localincomeamount] = stg.[apuk_localincomeamount],
		tgt.[apuk_localincomeamount_base] = stg.[apuk_localincomeamount_base],
		tgt.[apuk_membercurrency] = stg.[apuk_membercurrency],
		tgt.[apuk_membername] = stg.[apuk_membername],
		tgt.[apuk_membernumber] = stg.[apuk_membernumber],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_paymentamount] = stg.[apuk_paymentamount],
		tgt.[apuk_paymentamount_base] = stg.[apuk_paymentamount_base],
		tgt.[apuk_paymentdate] = stg.[apuk_paymentdate],
		tgt.[apuk_paymentreference] = stg.[apuk_paymentreference],
		tgt.[apuk_paymenttype] = stg.[apuk_paymenttype],
		tgt.[apuk_processedbyslteam] = stg.[apuk_processedbyslteam],
		tgt.[apuk_quote] = stg.[apuk_quote],
		tgt.[apuk_quote_entitytype] = stg.[apuk_quote_entitytype],
		tgt.[apuk_quotename] = stg.[apuk_quotename],
		tgt.[apuk_ukincomeamount] = stg.[apuk_ukincomeamount],
		tgt.[apuk_ukincomeamount_base] = stg.[apuk_ukincomeamount_base],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[exchangerate] = stg.[exchangerate],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[transactioncurrencyid] = stg.[transactioncurrencyid],
		tgt.[transactioncurrencyid_entitytype] = stg.[transactioncurrencyid_entitytype],
		tgt.[transactioncurrencyidname] = stg.[transactioncurrencyidname],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_internationalpayments] tgt
		INNER JOIN [staging_ce].[apuk_internationalpayments] stg
			ON tgt.[id] = stg.[id]
END
